// ── Sections and layout ──────────────────────────────────
let rowX = 0, rowY = 0;
function bottomOfPage() { return Math.max(0, ...page.children.map(n => n.y + n.height)); }
function startRow() { rowX = 0; rowY = bottomOfPage() + 96; }
