  set.children.forEach((c, i) => { c.x = 24 + (i % cols) * cellW; c.y = 24 + Math.floor(i / cols) * cellH; });
  set.resizeWithoutConstraints(24 + Math.min(cols, set.children.length) * cellW, 24 + Math.ceil(set.children.length / cols) * cellH);
