        await bindNum(ck, 'width', 'size/checkbox-size'); await bindNum(ck, 'height', 'size/checkbox-size'); await radius(ck, 'radius/pill'); ck.fills = [await paint('accent/accent')];
        ck.appendChild(await iconInst('Check', 'accent/on-accent', 14, 'Mark')); fr.appendChild(ck); ck.layoutPositioning = 'ABSOLUTE'; ck.x = 8; ck.y = 8;
