      cap.primaryAxisSizingMode = 'FIXED'; await bindNum(cap, 'height', 'size/media-tile-caption'); await bindNum(cap, 'itemSpacing', 'space/2'); await pad(cap, null, 'space/2', null, 'space/2');
      const nm = await text(kind === 'Folder' ? 'Trips' : 'IMG_0042.jpg', 'sm/Medium', sel ? 'accent/text' : 'text/1', 'Name'); cap.appendChild(nm); fill(nm); nm.textTruncation = 'ENDING';
      const mt = await text(kind === 'Folder' ? '40 items' : '4032 × 3024 · 3.1 MB', 'xs/Medium', 'text/3', 'Meta'); cap.appendChild(mt); fill(mt); mt.textTruncation = 'ENDING';
      vs.push(c);
