      if (sel) { const ring = figma.createEllipse(); ring.name = 'Ring'; ring.resize(44, 44); ring.x = -4; ring.y = -4; ring.fills = []; ring.strokes = [{ type: 'SOLID', color: rgb(DATA.accents[0].fill) }]; ring.strokeWeight = 2; ring.strokeAlign = 'INSIDE'; c.appendChild(ring); }
