    c.description = 'A step of the guided tour, beside the part it explains: surface/3, radius 2xl, elevation/overlay; title lg/Bold, body md text/2, progress dots (the current one an 18px accent pill), Back and Next. The page around is dimmed with the scrim.';
    await section('Tour', [c], 'surface/bg');
